using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language." },
            new() { Id = 5, Name = "Biology", Code = "BIO", Description = "Study of living organisms and their interactions." },
        };

        _courses = new List<Course>
        {
            new()
            {
                Id = 1, Title = "Introduction to Programming", Code = "CS101",
                Description = "Fundamentals of programming using C#. Covers variables, control flow, data structures, and object-oriented principles.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen",
                InstructorBio = "Dr. Chen has 15 years of industry experience and specializes in software engineering education.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
            },
            new()
            {
                Id = 2, Title = "Data Structures and Algorithms", Code = "CS201",
                Description = "Study of fundamental data structures (lists, trees, graphs) and algorithm design techniques including sorting, searching, and dynamic programming.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Park",
                InstructorBio = "Dr. Park's research focuses on algorithm optimization and competitive programming.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = true
            },
            new()
            {
                Id = 3, Title = "Database Systems", Code = "CS340",
                Description = "Relational database design, SQL, normalization, indexing, and transaction processing.",
                Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez",
                InstructorBio = "Dr. Lopez worked at Oracle for a decade before joining academia. She specializes in distributed databases.",
                DepartmentId = 1, DepartmentName = "Computer Science", IsFeatured = false
            },
            new()
            {
                Id = 4, Title = "Calculus I", Code = "MATH101",
                Description = "Limits, derivatives, and integrals of single-variable functions with applications.",
                Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Nguyen",
                InstructorBio = "Dr. Nguyen is an award-winning educator known for making complex math concepts accessible.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = true
            },
            new()
            {
                Id = 5, Title = "Linear Algebra", Code = "MATH220",
                Description = "Vector spaces, linear transformations, matrices, determinants, and eigenvalues.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emily Watson",
                InstructorBio = "Dr. Watson researches applications of linear algebra in machine learning and data science.",
                DepartmentId = 2, DepartmentName = "Mathematics", IsFeatured = false
            },
            new()
            {
                Id = 6, Title = "Classical Mechanics", Code = "PHYS201",
                Description = "Newtonian mechanics, conservation laws, rotational motion, oscillations, and waves.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Alan Foster",
                InstructorBio = "Dr. Foster is a theoretical physicist with published research in gravitational dynamics.",
                DepartmentId = 3, DepartmentName = "Physics", IsFeatured = true
            },
            new()
            {
                Id = 7, Title = "Quantum Physics", Code = "PHYS401",
                Description = "Introduction to quantum mechanics: wave functions, Schrödinger equation, and quantum states.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Dr. Alan Foster",
                InstructorBio = "Dr. Foster is a theoretical physicist with published research in gravitational dynamics.",
                DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false
            },
            new()
            {
                Id = 8, Title = "Creative Writing", Code = "ENG210",
                Description = "Workshop-based course developing skills in fiction, poetry, and creative nonfiction.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Prof. Diana Hart",
                InstructorBio = "Prof. Hart is a published novelist and poet with three National Book Award nominations.",
                DepartmentId = 4, DepartmentName = "English", IsFeatured = true
            },
            new()
            {
                Id = 9, Title = "American Literature", Code = "ENG305",
                Description = "Survey of American literature from colonial period to the present, exploring major movements and authors.",
                Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Thomas Reed",
                InstructorBio = "Dr. Reed specializes in 20th-century American fiction and has published extensively on Faulkner.",
                DepartmentId = 4, DepartmentName = "English", IsFeatured = false
            },
            new()
            {
                Id = 10, Title = "Molecular Biology", Code = "BIO301",
                Description = "Structure and function of biological macromolecules, gene expression, and cellular processes.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Karen Patel",
                InstructorBio = "Dr. Patel's research lab focuses on gene therapy and CRISPR applications.",
                DepartmentId = 5, DepartmentName = "Biology", IsFeatured = false
            },
            new()
            {
                Id = 11, Title = "Ecology and Evolution", Code = "BIO250",
                Description = "Principles of ecology, population dynamics, natural selection, and speciation.",
                Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Michael Torres",
                InstructorBio = "Dr. Torres conducts field research in tropical ecosystems and biodiversity conservation.",
                DepartmentId = 5, DepartmentName = "Biology", IsFeatured = true
            },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.DepartmentName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

