@page "/"
@using UniversityCourseCatalog.Services

<PageTitle>University Course Catalog</PageTitle>

<h1>University Course Catalog</h1>
<p class="lead">Welcome to the university course catalog. Browse departments, explore courses, and submit enrollment requests.</p>

<h2 class="mt-4">Featured Courses</h2>
<div class="row">
    @foreach (var course in FeaturedCourses)
    {
        <div class="col-md-6 col-lg-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@course.Code — @course.Title</h5>
                    <p class="card-text text-muted">@course.DepartmentName · @course.Credits credits</p>
                    <p class="card-text">@Truncate(course.Description, 100)</p>
                    <a href="/courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                </div>
            </div>
        </div>
    }
</div>

<h2 class="mt-5">Departments</h2>
<div class="list-group">
    @foreach (var dept in Departments)
    {
        <a href="/courses?departmentId=@dept.Id" class="list-group-item list-group-item-action">
            <strong>@dept.Code</strong> — @dept.Name
            <br /><small class="text-muted">@dept.Description</small>
        </a>
    }
</div>

@code {
    [Inject] private CatalogService CatalogService { get; set; } = default!;

    private List<UniversityCourseCatalog.Models.Course> FeaturedCourses { get; set; } = new();
    private List<UniversityCourseCatalog.Models.Department> Departments { get; set; } = new();

    protected override void OnInitialized()
    {
        FeaturedCourses = CatalogService.GetFeaturedCourses();
        Departments = CatalogService.GetDepartments();
    }

    private static string Truncate(string text, int maxLength) =>
        text.Length <= maxLength ? text : text[..maxLength] + "…";
}

@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1>Courses</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title, code, or instructor..." />
    </div>
    <div class="col-md-4">
        <select name="departmentId" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (Courses.Count == 0)
{
    <div class="alert alert-info">No courses found matching your criteria.</div>
}
